#!/usr/bin/env python3
"""Dependency-free structural validation. Run from any directory."""
from pathlib import Path
from html.parser import HTMLParser
from urllib.parse import urlsplit, unquote
import json, subprocess, xml.etree.ElementTree as ET
root=Path(__file__).resolve().parents[1]
errors=[]; checks=[]
class Page(HTMLParser):
 def __init__(self): super().__init__();self.ids=[];self.refs=[];self.h1=0;self.lang=False;self.viewport=False;self.noindex=False
 def handle_starttag(self,tag,attrs):
  a=dict(attrs)
  if 'id' in a:self.ids.append(a['id'])
  if tag=='h1':self.h1+=1
  if tag=='html':self.lang=bool(a.get('lang'))
  if tag=='meta' and a.get('name')=='viewport':self.viewport=True
  if tag=='meta' and a.get('name')=='robots':self.noindex='noindex' in a.get('content','')
  if tag=='img' and 'alt' not in a:errors.append('Missing alt: '+str(a))
  for attr in ['href','src']:
   if attr in a:self.refs.append(a[attr])
for f in root.rglob('*.html'):
 p=Page();p.feed(f.read_text()); rel=str(f.relative_to(root))
 for valid,name in [(p.h1==1,'one h1'),(p.lang,'language'),(p.viewport,'viewport'),(p.noindex,'preview noindex'),(len(p.ids)==len(set(p.ids)),'unique IDs')]:
  if not valid:errors.append(rel+': '+name)
 for ref in p.refs:
  u=urlsplit(ref)
  if u.scheme or u.netloc:errors.append(rel+': unexpected external reference '+ref);continue
  target=(f.parent/unquote(u.path)).resolve() if u.path else f
  if not target.exists():errors.append(rel+': missing '+ref)
  if u.fragment and target==f and u.fragment not in p.ids:errors.append(rel+': missing anchor '+ref)
 checks.append({'file':rel,'references':len(p.refs),'h1':p.h1})
for f in root.rglob('*.svg'):
 try:ET.parse(f)
 except Exception as e:errors.append(str(f)+': '+str(e))
for f in root.rglob('*.js'):
 result=subprocess.run(['node','--check',str(f)],capture_output=True,text=True)
 if result.returncode:errors.append(result.stderr)
print(json.dumps({'status':'pass' if not errors else 'fail','html':checks,'svg_count':len(list(root.rglob('*.svg'))),'js_count':len(list(root.rglob('*.js'))),'errors':errors},indent=2))
raise SystemExit(bool(errors))

